/* Dependency-free interactive Pareto SVG. Snapshot files are generated by web/build_site.py. */
'use strict';
const $ = id => document.getElementById(id);
const palette = {'OpenAI':'#147a65','Anthropic':'#d27946','Google':'#517bb5','Microsoft':'#9365b5','GitHub':'#7b5aa6','xAI':'#657683','Alibaba':'#c48b2c','DeepSeek':'#c55b5b','Moonshot AI':'#c35c7b','MiniMax':'#ab7a43','Z.ai':'#c15e6d','ByteDance':'#c27452','Other':'#8999a3'};
let db = null;
let chosenProviders = new Set(), chosenModels = new Set(), chartKey = '', labelMode='auto';
const ids = Array.from({length:30},(_,i)=>i);
const fmt = v => Number(v).toLocaleString('en-US',{maximumFractionDigits:2});
const costfmt = v => '$'+Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:v<.1?4:2});
const escapeHtml = v => String(v).replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));
function modelKey(m){return m.provider+'\u0000'+m.model}
function pointKey(p){return p.provider+'\u0000'+p.model}
function chart(){return db.charts.find(c=>c.id===chartKey)||db.charts[0]}
function currentPoints(){return chart().points.filter(p=>chosenProviders.has(p.provider)&&chosenModels.has(pointKey(p)))}
function checkedModels(){return db.catalog.filter(m=>chosenModels.has(modelKey(m)))}
function redrawSelectors(){
 let providerNames=[...new Set(db.catalog.map(c=>c.provider))].sort();
 let src=$('model-search').value.trim().toLowerCase();
 $('providers').replaceChildren(...providerNames.map(pr=>{
  const count=db.catalog.filter(m=>m.provider===pr).length;
  const cn=db.catalog.some(m=>m.provider===pr && m.china);
  const l=document.createElement('label');l.className='checkrow';
  const input=document.createElement('input'); input.type='checkbox';input.checked=chosenProviders.has(pr);input.setAttribute('aria-label','Provider '+pr);input.addEventListener('change',()=>{input.checked?chosenProviders.add(pr):chosenProviders.delete(pr);draw();});
  l.append(input);let sp=document.createElement('span');sp.textContent=pr;l.append(sp);
  if(cn){let tag=document.createElement('em');tag.textContent='CN';l.append(tag)}let ct=document.createElement('small');ct.textContent=String(count);l.append(ct);return l;
 }));
 let ms=db.catalog.filter(m=>chosenProviders.has(m.provider)&&(!src||(m.provider+' '+m.model).toLowerCase().includes(src)));
 $('models').replaceChildren(...ms.map(m=>{
   let l=document.createElement('label');l.className='checkrow';let chk=document.createElement('input');chk.type='checkbox';chk.checked=chosenModels.has(modelKey(m));chk.setAttribute('aria-label','Model '+m.model);chk.addEventListener('change',()=>{chk.checked?chosenModels.add(modelKey(m)):chosenModels.delete(modelKey(m));draw();});
   l.append(chk);let sp=document.createElement('span');sp.textContent=m.model;sp.title=m.provider+' — '+m.model;l.append(sp);return l;
 }));
 $('model-count').textContent=ms.length+' shown';$('provider-count').textContent=chosenProviders.size+' / '+providerNames.length;
 $('filter-total').textContent=checkedModels().length+' models selected';
}
function reset(){chosenProviders=new Set(db.catalog.map(m=>m.provider));chosenModels=new Set(db.catalog.map(modelKey));$('model-search').value='';draw();}
function providerColor(pr){return palette[pr]||palette.Other}
function frontier(ps){let a=[...ps].sort((a,b)=>a.cost-b.cost||b.score-a.score), top=-Infinity,out=[];
 for(const p of a){if(p.score>top+1e-9){out.push(p);top=p.score}}
 return out;
}
function svgEl(tag,attrs={},parent){let e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,String(v));if(parent)parent.append(e);return e}
function textNode(parent,x,y,text,attr={}){let e=svgEl('text',{x,y,...attr},parent);e.textContent=text;return e}
function drawGraph(points){
 const host=$('chart-area');host.replaceChildren();if(points.length===0){host.innerHTML='<div class="empty">No measured benchmark points match the current filters. Select other models or a snapshot.</div>';return;}
 const svg=svgEl('svg',{viewBox:'0 0 1360 450',role:'img','aria-label':chart().label+'; full range left, low-cost zoom right.'},host);
 const xMax=Math.max(...points.map(p=>p.cost))*1.08||1;const yMax=Math.min(100,Math.max(...points.map(p=>p.score))+7);const yMin=Math.max(0,Math.min(...points.map(p=>p.score))-9);let zoomX=chart().zoom_max||Math.min(5,xMax);zoomX=Math.min(zoomX,xMax);if(zoomX<.1)zoomX=xMax;
 const panels=[{x:64,y:42,w:600,h:338,max:xMax,title:'Full cost range'},{x:738,y:42,w:575,h:338,max:zoomX,title:'Low-cost zoom'}];
 const provs=[...new Set(points.map(p=>p.provider))];const best=frontier(points);
 const pos=(p,box)=>[box.x+p.cost/box.max*box.w,box.y+box.h-(p.score-yMin)/(yMax-yMin)*box.h];
 for(const box of panels){
  textNode(svg,box.x,22,box.title,{class:'svg-title'});svgEl('rect',{x:box.x,y:box.y,width:box.w,height:box.h,class:'svg-panel'},svg);
  for(let k=0;k<=5;k++){const yy=box.y+box.h*k/5,score=yMax-(yMax-yMin)*k/5;svgEl('line',{x1:box.x,x2:box.x+box.w,y1:yy,y2:yy,class:'svg-grid'},svg);textNode(svg,box.x-10,yy+4,fmt(score)+'%',{'text-anchor':'end',class:'svg-tick'});
  const xx=box.x+box.w*k/5;svgEl('line',{x1:xx,x2:xx,y1:box.y,y2:box.y+box.h,class:'svg-grid'},svg);textNode(svg,xx,box.y+box.h+19,costfmt(box.max*k/5),{'text-anchor':'middle',class:'svg-tick'});}
  const visible=points.filter(p=>p.cost<=box.max),f=best.filter(p=>p.cost<=box.max);if(f.length>1){const path=f.map((p,i)=>{const [xx,yy]=pos(p,box);return(i?'L':'M')+xx.toFixed(2)+','+yy.toFixed(2)}).join(' ');svgEl('path',{d:path,class:'svg-frontier'},svg)}
  // Smart labels reduce clutter on busy AA v2.1; all points still have focusable circles and tooltips.
  const labelSlots=[];
  for(const p of visible){const [xx,yy]=pos(p,box);const color=providerColor(p.provider);
   const dot=svgEl('circle',{cx:xx,cy:yy,r:6,fill:color,stroke:'#fff','stroke-width':1.3,tabindex:0,role:'button','aria-label':p.provider+' '+p.model+' '+p.effort+' score '+p.score+' cost '+p.cost,class:'svg-point'},svg);
   dot.addEventListener('mouseenter',e=>tooltip(p,e));dot.addEventListener('mousemove',e=>moveTip(e));dot.addEventListener('mouseleave',hideTip);dot.addEventListener('focus',e=>tooltip(p,e));dot.addEventListener('blur',hideTip);
   if(labelMode==='none')continue;
   const dense=visible.length>18 && labelMode==='auto';if(dense && !best.includes(p) && p.cost<box.max*.6)continue;
   const label=p.model+(p.effort && p.effort!=='default'?' / '+p.effort:'');const w=Math.min(245,label.length*5.4+5);let lx=Math.max(box.x+4,Math.min(box.x+box.w-w-5,xx+9));let ly=Math.max(box.y+14,Math.min(box.y+box.h-5,yy-9));
   if(labelMode==='auto'){let ix=0;while(labelSlots.some(t=>Math.abs(lx-t.x)<Math.min(w,t.w)+2 && Math.abs(ly-t.y)<13) && ix++<18)ly=box.y+14+((ly-box.y+ix*19)%(box.h-20));if(labelSlots.some(t=>Math.abs(lx-t.x)<Math.min(w,t.w)+2&&Math.abs(ly-t.y)<13))continue}
   labelSlots.push({x:lx,y:ly,w});textNode(svg,lx,ly,label,{fill:color,class:'svg-label'});
  }
 }
 textNode(svg,355,434,'Estimated cost per benchmark task (USD, linear)',{'text-anchor':'middle',class:'svg-tick'});textNode(svg,1010,434,'Estimated cost per benchmark task (USD, linear)',{'text-anchor':'middle',class:'svg-tick'});
 $('chart-legend').textContent=provs.map(p=>p+' ●').join('   ')+'   — Pareto frontier';
}
function tooltip(p,e){const box=$('tooltip');box.hidden=false;box.innerHTML=`<strong>${escapeHtml(p.model)} / ${escapeHtml(p.effort)}</strong><small>${escapeHtml(p.provider)} · ${escapeHtml(p.harness||'Benchmark')} ${p.china?'· China-based':''}</small><div>Score: <b>${fmt(p.score)}</b> · Estimated cost: <b>${costfmt(p.cost)}</b></div><div>Cost factor: ×${fmt(p.discount)}</div>${p.source?`<small>Source: ${escapeHtml(p.source).slice(0,90)}</small>`:''}`;moveTip(e)}
function moveTip(e){let b=$('tooltip');if(b.hidden)return;const x=e.clientX??innerWidth/2,y=e.clientY??innerHeight/2;b.style.left=Math.max(8,Math.min(x+12,innerWidth-290))+'px';b.style.top=Math.max(8,Math.min(y+12,innerHeight-125))+'px'}
function hideTip(){$('tooltip').hidden=true}
function drawTable(points){const sorted=[...points].sort((a,b)=>a.cost-b.cost);$('rows').replaceChildren(...sorted.map(p=>{let tr=document.createElement('tr');for(const v of [p.provider,p.model+' / '+p.effort,fmt(p.score),costfmt(p.cost),'×'+fmt(p.discount)]){let td=document.createElement('td');td.textContent=v;tr.append(td)}return tr}));$('table-meta').textContent=points.length+' results';}
function draw(){if(!db)return;redrawSelectors();const c=chart(),points=currentPoints();$('point-count').textContent=points.length+' scored variants';$('chart-title').textContent=c.label;$('chart-meta').textContent=c.snapshot+' · '+c.benchmark+' · '+c.version+' · '+c.points.length+' scored points available';
 $('promo-line').textContent=db.promos.map(p=>`${p.label}: ${p.discount} until ${p.until}`).join('   ·   ');
 drawGraph(points);drawTable(points);const imageId=c.id;
 const staticFiles=db.static_charts?.[imageId];$('asset-links').replaceChildren();if(staticFiles){for(const [ext,url] of Object.entries(staticFiles)){let a=document.createElement('a');a.href=url;a.textContent='Download '+ext.toUpperCase();a.target='_blank';a.rel='noopener';$('asset-links').append(a)}}
 let act=document.createElement('a');act.href='https://github.com/ChrisTorng/coding-agent-pareto/actions';act.textContent='All GHA artifacts';act.target='_blank';act.rel='noopener';$('asset-links').append(act);
}
function exportCsv(){const p=currentPoints();const fields=['provider','model','effort','score','cost','base_cost','discount','harness','source'];const esc=v=>'"'+String(v??'').replaceAll('"','""')+'"';let csv=[fields.join(','),...p.map(r=>fields.map(f=>esc(r[f])).join(','))].join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=chart().id+'-filtered.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),4000)}
async function main(){try{let res=await fetch('./data.json',{cache:'no-store'});if(!res.ok)throw Error('HTTP '+res.status);db=await res.json();if(!db.charts?.length||!db.catalog?.length)throw Error('Missing catalog/charts');chosenProviders=new Set(db.catalog.map(m=>m.provider));chosenModels=new Set(db.catalog.map(modelKey));chartKey=db.charts[0].id;
 for(const c of db.charts){let opt=document.createElement('option');opt.value=c.id;opt.textContent=c.label+' ('+c.snapshot+')';$('chart-picker').append(opt)}
 $('chart-picker').addEventListener('change',e=>{chartKey=e.target.value;draw()});$('label-mode').addEventListener('change',e=>{labelMode=e.target.value;draw()});$('select-all').addEventListener('click',reset);$('reset-filter').addEventListener('click',reset);$('exclude-china').addEventListener('click',()=>{chosenProviders=new Set(db.catalog.filter(m=>!m.china).map(m=>m.provider));chosenModels=new Set(db.catalog.filter(m=>!m.china).map(modelKey));draw()});$('model-search').addEventListener('input',()=>redrawSelectors());$('export-csv').addEventListener('click',exportCsv);draw();
 }catch(e){$('chart-area').textContent='Unable to load model data: '+e.message;console.error(e)}}
main();